  ('ebcc7910-0000-4000-a000-012100000003'::uuid, 'Elevator out of service — Tower A', 'Building tenants', '2026-10-19'::date, '2026-10-21'::date, 'Urgent', 'Sent', '77bc4a76-4959-4a23-a5ae-eaccdf731bb3'::uuid, '{"delivery":{"total":5,"sent":0,"failed":0,"notSent":0,"skipped":0,"logged":5,"errors":[],"at":"2026-10-19T02:45:00.000Z"},"sentAt":"2026-10-19T02:45:00.000Z"}'::jsonb, '2026-10-19T00:49:00.000Z'::timestamptz, '2026-10-19T00:49:00.000Z'::timestamptz, null, 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3'::uuid, 'ebcc7910-0000-4000-a000-000300000001'::uuid, 'The Marlowe', 'Portal', '2026-10-19'::date, 'The Tower A elevator is out of service while Vertical Lift replaces a door operator. Expected back in service within 48 hours. Need help with groceries or deliveries? Call the leasing office and we''ll lend a hand.', 'ebcc7910-0000-4000-a000-000400000001'::uuid, 'Tower A', '2026-10-19T02:45:00.000Z'::timestamptz),
  ('ebcc7910-0000-4000-a000-012100000004'::uuid, 'Vendor invoices now go through the portal', 'Vendors', '2026-09-30'::date, '2026-11-18'::date, 'Normal', 'Sent', '77bc4a76-4959-4a23-a5ae-eaccdf731bb3'::uuid, '{"delivery":{"total":6,"sent":6,"failed":0,"notSent":0,"skipped":0,"logged":0,"errors":[],"at":"2026-09-30T05:00:00.000Z"},"sentAt":"2026-09-30T05:00:00.000Z"}'::jsonb, '2026-09-30T02:57:00.000Z'::timestamptz, '2026-09-30T02:57:00.000Z'::timestamptz, null, 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3'::uuid, null, '', 'Email', '2026-09-30'::date, 'From November 1, please submit invoices through the vendor portal against each work order. Invoices submitted there are approved and paid faster — no more emailed PDFs.', null, '', '2026-09-30T05:00:00.000Z'::timestamptz),
  ('ebcc7910-0000-4000-a000-012100000005'::uuid, 'New owner statement layout', 'Owners', null, null, 'Low', 'Draft', '77bc4a76-4959-4a23-a5ae-eaccdf731bb3'::uuid, '{}'::jsonb, '2026-10-13T09:50:00.000Z'::timestamptz, '2026-10-13T09:50:00.000Z'::timestamptz, null, 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3'::uuid, 'ebcc7910-0000-4000-a000-000300000002'::uuid, 'Pinecrest Commons', 'Portal', null, 'Starting with the October statement, owner statements group income and expenses by property and show the management fee on its own line.', null, '', default),
  ('ebcc7910-0000-4000-a000-012100000006'::uuid, 'Water shut-off — Tower A, Thursday 9am–1pm', 'Building tenants', '2026-10-22'::date, '2026-10-23'::date, 'High', 'Draft', '77bc4a76-4959-4a23-a5ae-eaccdf731bb3'::uuid, '{"activityNotes":"Window confirmed with Rainier Plumbing dispatch. Ready to schedule once the riser parts arrive."}'::jsonb, '2026-10-12T09:50:00.000Z'::timestamptz, '2026-10-12T09:50:00.000Z'::timestamptz, null, 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3'::uuid, 'ebcc7910-0000-4000-a000-000300000001'::uuid, 'The Marlowe', 'Email', '2026-10-22'::date, 'Rainier Plumbing will replace the main riser valve in Tower A on Thursday. Water will be off from 9am to 1pm. Please store water ahead of time and keep taps closed during the work.', 'ebcc7910-0000-4000-a000-000400000001'::uuid, 'Tower A', default),
  ('ebcc7910-0000-4000-a000-012100000007'::uuid, 'Winter weather preparedness', 'All tenants', '2026-10-29'::date, '2027-02-26'::date, 'Normal', 'Draft', '77bc4a76-4959-4a23-a5ae-eaccdf731bb3'::uuid, '{"activityNotes":"Hold until the first frost warning, then schedule."}'::jsonb, '2026-10-11T09:50:00.000Z'::timestamptz, '2026-10-11T09:50:00.000Z'::timestamptz, null, 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3'::uuid, null, '', 'Email', '2026-10-29'::date, 'Cold weather is on the way. Keep thermostats at 55°F or higher, open sink cabinets on freezing nights, and report any loss of heat through the resident portal right away.', null, '', default),
  ('ebcc7910-0000-4000-a000-012100000008'::uuid, 'Parking lot resurfacing — Pinecrest Commons', 'Property tenants', '2026-11-06'::date, '2026-11-09'::date, 'High', 'Draft', '77bc4a76-4959-4a23-a5ae-eaccdf731bb3'::uuid, '{}'::jsonb, '2026-10-10T09:50:00.000Z'::timestamptz, '2026-10-10T09:50:00.000Z'::timestamptz, null, 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3'::uuid, 'ebcc7910-0000-4000-a000-000300000002'::uuid, 'Pinecrest Commons', 'SMS', '2026-11-06'::date, 'The Pinecrest lot will be resurfaced over two days. Vehicles must be moved to street parking by 7am on the first day. Towing will be enforced.', null, '', default),
