insert into property.automations (id, name, trigger_rule, action_rule, audience, run_count, last_run_on, enabled, status, created_by, metadata, created_at, updated_at, deleted_at, project_id, trigger_event, action_type) values
  ('ebcc7910-0000-4000-a000-006700000001'::uuid, 'Late rent notice & escalation', null, null, null, 5, '2026-10-07'::date, false, 'Paused', '77bc4a76-4959-4a23-a5ae-eaccdf731bb3'::uuid, '{"trigger":{"daysOverdue":6,"minBalance":100},"conditionRules":[{"id":"rule-1","field":"balance","op":"gte","value":"100"},{"id":"rule-2","field":"status","op":"not_equals","value":"Past"}],"steps":[{"id":"ebcc7910-0000-4000-a000-013800000011","type":"send_email","config":{"recipient":"tenant","channel":"email","templateId":"ebcc7910-0000-4000-a000-006100000002","subject":"","body":""}},{"id":"ebcc7910-0000-4000-a000-013800000012","type":"update_status","config":{"status":"Late"}},{"id":"ebcc7910-0000-4000-a000-013800000013","type":"wait","config":{"days":5}},{"id":"ebcc7910-0000-4000-a000-013800000014","type":"notify","config":{"message":"{{tenant_name}} ({{unit}}) still owes {{balance_due}} — call today or serve a 14-day notice.","memberId":"ebcc7910-0000-4000-a000-006800000005","emailTeam":true}}],"canvas":{"positions":{"trigger":{"x":0,"y":0},"rule-1":{"x":340,"y":150},"rule-2":{"x":0,"y":300},"ebcc7910-0000-4000-a000-013800000011":{"x":340,"y":450},"ebcc7910-0000-4000-a000-013800000012":{"x":0,"y":600},"ebcc7910-0000-4000-a000-013800000013":{"x":340,"y":750},"ebcc7910-0000-4000-a000-013800000014":{"x":0,"y":900}}},"description":"Six days after rent is due: emails the late notice, marks the resident Late, and escalates to accounting if the balance is still open five days later.","activityNotes":"Late-notice wording reviewed with counsel — matches the WA lease addendum."}'::jsonb, '2026-05-23T06:00:00.000Z'::timestamptz, '2026-10-19T21:36:23.304Z'::timestamptz, null, 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3'::uuid, 'rent.overdue', 'workflow'),
  ('ebcc7910-0000-4000-a000-006700000002'::uuid, 'Weekly balance text', null, null, null, 10, '2026-10-19'::date, false, 'Paused', '77bc4a76-4959-4a23-a5ae-eaccdf731bb3'::uuid, '{"trigger":{"frequency":"weekly","weekday":"1","monthDay":1,"scope":"tenants_with_balance"},"conditionRules":[{"field":"balance","op":"gt","value":"50"},{"field":"balance","op":"lt","value":"5000"}],"steps":[{"id":"ebcc7910-0000-4000-a000-013800000021","type":"send_email","config":{"recipient":"tenant","channel":"sms","templateId":"ebcc7910-0000-4000-a000-012300000005","subject":"","body":""}}],"description":"Monday-morning text to every resident carrying a balance over $50.","activityNotes":"No SMS provider is connected yet — these texts are logged as not sent until one is."}'::jsonb, '2026-08-21T06:00:00.000Z'::timestamptz, '2026-10-19T21:36:23.304Z'::timestamptz, null, 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3'::uuid, 'schedule', 'workflow'),
  ('ebcc7910-0000-4000-a000-006700000003'::uuid, 'Move-in welcome', null, null, null, 5, '2026-10-19'::date, false, 'Paused', '77bc4a76-4959-4a23-a5ae-eaccdf731bb3'::uuid, '{"trigger":{},"conditionRules":[{"id":"rule-1","field":"unit","op":"is_set","value":""}],"steps":[{"id":"ebcc7910-0000-4000-a000-013800000031","type":"send_email","config":{"recipient":"tenant","channel":"email","templateId":"","subject":"Welcome to {{property}}","body":"Hi {{tenant_first_name}},\n\nWe''re looking forward to your move into {{unit}}. Rent of {{rent}} is due on {{due_date}}, and your portal is ready for payments and maintenance requests.\n\nReply to this email with any questions before move-in day.\n\n{{company_name}}"}},{"id":"ebcc7910-0000-4000-a000-013800000032","type":"notify","config":{"message":"Move-in scheduled for {{unit}} — confirm keys, utilities and the move-in inspection.","memberId":"","emailTeam":true}},{"id":"ebcc7910-0000-4000-a000-013800000033","type":"create_work_order","config":{"name":"Move-in inspection — {{unit}}","priority":"Medium","category":"Inspection","description":""}},{"id":"ebcc7910-0000-4000-a000-013800000034","type":"wait","config":{"days":7}},{"id":"ebcc7910-0000-4000-a000-013800000035","type":"send_email","config":{"recipient":"tenant","channel":"email","templateId":"","subject":"How''s the first week at {{property}}?","body":"Hi {{tenant_first_name}},\n\nYou''ve had a week in {{unit}} — is everything working as it should? Reply here or submit a maintenance request from your portal.\n\n{{company_name}}"}}],"builtIn":"move_in","canvas":{"positions":{"trigger":{"x":0,"y":0},"rule-1":{"x":0,"y":170},"ebcc7910-0000-4000-a000-013800000031":{"x":0,"y":340},"ebcc7910-0000-4000-a000-013800000032":{"x":0,"y":510},"ebcc7910-0000-4000-a000-013800000033":{"x":0,"y":680},"ebcc7910-0000-4000-a000-013800000034":{"x":0,"y":850},"ebcc7910-0000-4000-a000-013800000035":{"x":0,"y":1020}}},"description":"Welcome email, team heads-up, move-in inspection work order, an